def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]

    if all(a == 'D' for a in opp):
        return 'D'

    ret = 0
    opps = 0
    for i in range(n - 1):
        if my[i] == 'D' and opp[i] == 'C':
            opps += 1
            if opp[i + 1] == 'D':
                ret += 1
    ret_rate = ret / opps if opps > 0 else 0.5

    last_my = my[-1]
    last_opp = opp[-1]

    if n == 99:
        return 'D'

    if n >= 95:
        if ret_rate < 0.3:
            return 'D'
        else:
            if last_opp == 'D':
                return 'D'
            return 'C'

    if n >= 90:
        if ret_rate < 0.2:
            return 'D'

    if n >= 2 and history[-2][0] == 'D' and history[-2][1] == 'C' and history[-1][1] == 'D':
        return 'C'

    if last_opp == 'D':
        consec_d = 0
        for i in range(n - 1, -1, -1):
            if opp[i] == 'D':
                consec_d += 1
            else:
                break
        if consec_d >= 3:
            if n % 10 == 0:
                return 'C'
            return 'D'
        return 'D'

    if last_my == 'D':
        if ret_rate < 0.1 and opps >= 3:
            return 'D'
        return 'C'

    last_exploit = -1
    for i in range(n - 1, -1, -1):
        if my[i] == 'D' and opp[i] == 'C':
            last_exploit = i
            break

    if last_exploit == -1:
        if n >= 4:
            return 'D'
        return 'C'
    else:
        gap = n - last_exploit - 1
        desired_gap = int(1 + 10 * ret_rate)
        if n >= 80:
            desired_gap = min(desired_gap, 2)
        if gap >= desired_gap:
            return 'D'
        return 'C'
